/** Read-only YouTube Music home using the user's existing encrypted session. */
final class AccountMusic {
 interface Source {List<DiscoveryShelf> load(Context c,String process)throws Exception;}
 private static final String ORIGIN="https://music.youtube.com";
 private static final Map<String,Set<HttpURLConnection>> active=new ConcurrentHashMap<>();
 static void cancel(String process){for(String key:active.keySet())if(key.equals(process)||key.startsWith(process+"-")){Set<HttpURLConnection> connections=active.get(key);if(connections!=null)for(HttpURLConnection connection:connections)connection.disconnect();}}
 static String friendly(Exception error){String message=error.getMessage()==null?"":error.getMessage();if(DownloadErrors.rateLimited(message))return "YouTube Music is limiting requests. Wait a minute before refreshing.";if(message.contains("Reconnect")||message.contains("expired")||message.contains("could not verify")||message.contains("incomplete"))return "Reconnect YouTube from More to load account recommendations.";if(message.contains("No supported")||message.contains("No music picks"))return "Your account has no supported song picks yet. Listen on YouTube Music, then refresh.";return "Your account music couldn't refresh. Check your connection and retry.";}
 interface Transport {String send(String process,String path,String cookies,String auth,String body,String user,String visitor,String version)throws Exception;}
 static Transport transport=AccountMusic::http;
 static JSONObject context(SessionAuth auth)throws Exception{JSONObject client=new JSONObject().put("clientName","WEB_REMIX").put("clientVersion",auth.clientVersion).put("visitorData",auth.visitorData).put("hl",Locale.getDefault().getLanguage());JSONObject user=new JSONObject().put("lockedSafetyMode",false);if(!auth.dataSyncId.isEmpty())user.put("onBehalfOfUser",auth.dataSyncId);return new JSONObject().put("client",client).put("user",user).put("request",new JSONObject().put("internalExperimentFlags",new JSONArray()).put("useSsl",true));}
 private static String secret(SessionAuth auth)throws Exception{Map<String,String> cookies=cookies(YouTubeCookies.netscape(auth.cookie));String value=cookies.getOrDefault("SAPISID",cookies.getOrDefault("__Secure-3PAPISID",cookies.getOrDefault("__Secure-1PAPISID","")));if(value.isEmpty())throw new IOException("Reconnect YouTube to refresh account recommendations.");return value;}
 private static JSONObject post(String process,String path,SessionAuth auth,JSONObject body)throws Exception{return new JSONObject(transport.send(process,path,auth.cookie,authorization(secret(auth),System.currentTimeMillis()/1000),body.toString(),auth.authUser,auth.visitorData,auth.clientVersion));}
 static SessionAuth verifyAccount(SessionAuth candidate,String process)throws Exception{if(!candidate.complete())throw new IOException("YouTube Music session is incomplete.");JSONObject response=post(process,"/youtubei/v1/account/account_menu?prettyPrint=false",candidate,new JSONObject().put("context",context(candidate)));JSONObject header=find(response,"activeAccountHeaderRenderer",0);String name=header==null?"":text(header.optJSONObject("accountName"));if(name.isBlank())throw new IOException("YouTube Music could not verify this account. Finish sign-in, choose your account, and retry.");String avatar="";JSONObject photo=header.optJSONObject("accountPhoto");JSONArray photos=photo==null?null:photo.optJSONArray("thumbnails");if(photos!=null)for(int i=0;i<photos.length();i++){JSONObject image=photos.optJSONObject(i);if(image!=null&&AccountAvatar.allowed(image.optString("url")))avatar=image.optString("url");}return candidate.identity(name).avatar(avatar);}
 static List<DiscoveryShelf> load(Context c,String process)throws Exception{
  String scope=YouTubeSession.fingerprint(c);SessionAuth auth=YouTubeSession.read(c);if(auth==null)throw new IOException("Connect YouTube to load your account's music.");
  if(!auth.complete()){String html=transport.send(process,"/",auth.cookie,null,null,"0","","");String version=config(html,"INNERTUBE_CLIENT_VERSION"),visitor=config(html,"VISITOR_DATA"),user=config(html,"SESSION_INDEX");if(!user.matches("[0-9]{1,3}"))user="0";auth=SessionAuth.capture(auth.cookie,visitor,config(html,"DATASYNC_ID"),user,version);}
  boolean[] verified={false};JSONObject home=browse(process,auth,"FEmusic_home");authorize(home,auth,process,verified);List<DiscoveryShelf> result=parse(home);Exception optionalFailure=null;
  if(result.size()<4)for(String id:playlists(home)){if(result.size()>=4)break;try{JSONObject playlist=id.startsWith("VL")?browse(process,auth,id):post(process,"/youtubei/v1/next?prettyPrint=false",auth,new JSONObject().put("context",context(auth)).put("playlistId",id).put("enablePersistentPlaylistPanel",true).put("isAudioOnly",true).put("tunerSettingValue","AUTOMIX_SETTING_NORMAL"));authorize(playlist,auth,process,verified);for(DiscoveryShelf shelf:parse(playlist)){if(result.size()==4)break;result.add(shelf);}}catch(Exception error){if(Thread.currentThread().isInterrupted()||error instanceof InterruptedIOException)throw error;optionalFailure=error;if(DownloadErrors.rateLimited(error.getMessage()))break;}}
  if(result.isEmpty())try{JSONObject likes=browse(process,auth,"VLLM");authorize(likes,auth,process,verified);for(DiscoveryShelf shelf:parse(likes)){if(result.size()==4)break;result.add(new DiscoveryShelf("Your YouTube Music likes","From your connected account · Home picks were unavailable",shelf.tracks));}}catch(Exception error){if(Thread.currentThread().isInterrupted()||error instanceof InterruptedIOException)throw error;if(optionalFailure==null)optionalFailure=error;}
  if(result.isEmpty()&&optionalFailure!=null)throw optionalFailure;
  if(!scope.equals(YouTubeSession.fingerprint(c)))throw new InterruptedIOException("Account changed during refresh.");if(result.isEmpty())throw new IOException("No supported song recommendations in your YouTube Music home yet. Listen on YouTube Music and refresh later.");return result;
 }
 private static void authorize(JSONObject response,SessionAuth auth,String process,boolean[] verified)throws Exception{JSONObject context=response.optJSONObject("responseContext"),web=context==null?null:context.optJSONObject("mainAppWebResponseContext");if(web!=null&&web.has("loggedOut")){requireSignedIn(response);return;}if(response.has("error"))throw new IOException("YouTube Music could not load this shelf.");if(!verified[0]){verifyAccount(auth,process+"-identity");verified[0]=true;}}
 static Map<String,String> cookies(String text){Map<String,String> values=new LinkedHashMap<>();for(String line:text.split("\\r?\\n")){if(line.startsWith("#HttpOnly_"))line=line.substring(10);else if(line.startsWith("#"))continue;String[] fields=line.split("\\t",-1);if(fields.length==7&&(fields[0].equals(".youtube.com")||fields[0].equals("youtube.com")||fields[0].equals("music.youtube.com"))&&fields[5].matches("[A-Za-z0-9_-]+")&&!fields[6].matches("(?s).*[\\x00-\\x20\\x7f;].*"))values.put(fields[5],fields[6]);}return values;}
 static String authorization(String secret,long timestamp)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-1").digest((timestamp+" "+secret+" "+ORIGIN).getBytes(StandardCharsets.UTF_8));StringBuilder hash=new StringBuilder();for(byte value:digest)hash.append(String.format(Locale.ROOT,"%02x",value&255));return "SAPISIDHASH "+timestamp+"_"+hash;}
 private static JSONObject browse(String process,SessionAuth auth,String id)throws Exception{return post(process,"/youtubei/v1/browse?prettyPrint=false",auth,new JSONObject().put("context",context(auth)).put("browseId",id));}
 static void requireSignedIn(JSONObject response)throws IOException{JSONObject context=response.optJSONObject("responseContext"),web=context==null?null:context.optJSONObject("mainAppWebResponseContext");if(web==null||!web.has("loggedOut")||web.optBoolean("loggedOut",true))throw new IOException("Your YouTube Music session expired. Reconnect YouTube from More.");}
 static String config(String html,String key){Matcher match=Pattern.compile("\""+key+"\"\\s*:\\s*\"([^\"]{1,1000})\"").matcher(html);return match.find()?match.group(1):"";}
 private static String http(String process,String path,String cookies,String auth,String body,String authUser,String visitor,String version)throws Exception{
  if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Account refresh cancelled.");HttpURLConnection connection=(HttpURLConnection)new URL(ORIGIN+path).openConnection();Set<HttpURLConnection> connections=active.computeIfAbsent(process,k->ConcurrentHashMap.newKeySet());connections.add(connection);
  try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(12000);connection.setRequestProperty("User-Agent","Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36");connection.setRequestProperty("Cookie",cookies);connection.setRequestProperty("Origin",ORIGIN);connection.setRequestProperty("Referer",ORIGIN+"/");connection.setRequestProperty("X-Goog-AuthUser",authUser);connection.setRequestProperty("X-Origin",ORIGIN);connection.setRequestProperty("X-Goog-Api-Format-Version","1");connection.setRequestProperty("X-YouTube-Client-Name","67");if(!version.isEmpty())connection.setRequestProperty("X-YouTube-Client-Version",version);if(!visitor.isEmpty())connection.setRequestProperty("X-Goog-Visitor-Id",visitor);if(auth!=null){connection.setRequestProperty("Authorization",auth);connection.setRequestProperty("X-Youtube-Bootstrap-Logged-In","true");}if(body!=null){connection.setRequestMethod("POST");connection.setRequestProperty("Content-Type","application/json");connection.setDoOutput(true);try(OutputStream out=connection.getOutputStream()){out.write(body.getBytes(StandardCharsets.UTF_8));}}
   int status=connection.getResponseCode();if(status==429)throw new IOException("HTTP 429: YouTube Music is limiting requests. Try later.");if(status==401||status==403||status>=300&&status<400)throw new IOException("Reconnect YouTube to refresh account recommendations.");if(status!=200)throw new IOException("YouTube Music is unavailable. Try later.");try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Account refresh cancelled.");if(out.size()+n>8*1024*1024)throw new IOException("Account response is too large.");out.write(buffer,0,n);}return out.toString(StandardCharsets.UTF_8.name());}
  }finally{connections.remove(connection);if(connections.isEmpty())active.remove(process,connections);connection.disconnect();}
 }
 static List<DiscoveryShelf> parse(JSONObject root){List<DiscoveryShelf> shelves=new ArrayList<>();walkShelves(root,shelves,0);return shelves;}
 private static void walkShelves(Object node,List<DiscoveryShelf> out,int depth){if(depth>32||out.size()>=4)return;if(node instanceof JSONObject){JSONObject object=(JSONObject)node;for(String renderer:List.of("musicCarouselShelfRenderer","musicImmersiveCarouselShelfRenderer","musicShelfRenderer","musicPlaylistShelfRenderer","playlistPanelRenderer")){JSONObject shelf=object.optJSONObject(renderer);if(shelf!=null){List<Track> tracks=new ArrayList<>();walkSongs(shelf.optJSONArray("contents"),tracks,0);if(!tracks.isEmpty()){String title=text(shelf.optJSONObject("title"));if(title.isBlank())title=text(find(shelf.optJSONObject("header"),"title",0));if(title.isBlank())title="From your YouTube Music";out.add(new DiscoveryShelf(title,"From your connected YouTube Music account",tracks));}return;}}for(Iterator<String> keys=object.keys();keys.hasNext();)walkShelves(object.opt(keys.next()),out,depth+1);}else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<Math.min(200,array.length());i++)walkShelves(array.opt(i),out,depth+1);}}
 private static void walkSongs(Object node,List<Track> songs,int depth){if(node==null||depth>20||songs.size()>=12)return;if(node instanceof JSONObject){JSONObject object=(JSONObject)node;JSONObject wrapper=object.optJSONObject("playlistPanelVideoWrapperRenderer");if(wrapper!=null){walkSongs(wrapper.optJSONObject("primaryRenderer"),songs,depth+1);return;}for(String renderer:List.of("musicTwoRowItemRenderer","musicResponsiveListItemRenderer","playlistPanelVideoRenderer")){JSONObject item=object.optJSONObject(renderer);if(item!=null){Track track=song(item);if(track!=null&&songs.stream().noneMatch(t->t.id.equals(track.id)))songs.add(track);return;}}for(Iterator<String> keys=object.keys();keys.hasNext();)walkSongs(object.opt(keys.next()),songs,depth+1);}else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<Math.min(100,array.length());i++)walkSongs(array.opt(i),songs,depth+1);}}
 private static Track song(JSONObject item){if(item.optBoolean("isUnplayable")||item.has("unplayableText"))return null;JSONObject watch=null;String type="";for(String section:List.of("navigationEndpoint","overlay","thumbnailOverlay")){JSONObject candidate=find(item.optJSONObject(section),"watchEndpoint",0);if(candidate!=null){JSONObject config=find(candidate,"watchEndpointMusicConfig",0);String value=config==null?"":config.optString("musicVideoType");if(watch==null){watch=candidate;type=value;}if(!value.isEmpty()){watch=candidate;type=value;break;}}}if(watch==null)watch=find(item,"watchEndpoint",0);String id=watch==null?item.optString("videoId"):watch.optString("videoId",item.optString("videoId"));if(watch!=null&&type.isEmpty()){JSONObject config=find(watch,"watchEndpointMusicConfig",0);type=config==null?"":config.optString("musicVideoType");}if(!id.matches("[A-Za-z0-9_-]{11}")||(!type.isEmpty()&&!List.of("MUSIC_VIDEO_TYPE_ATV","MUSIC_VIDEO_TYPE_OMV").contains(type))||type.isEmpty()&&!musicCredit(item,0))return null;
  String title=text(item.optJSONObject("title")),artist="";JSONObject subtitle=item.optJSONObject("subtitle");if(subtitle==null)subtitle=item.optJSONObject("shortBylineText");if(subtitle==null)subtitle=item.optJSONObject("longBylineText");JSONArray flex=item.optJSONArray("flexColumns");if(flex!=null){if(flex.length()>0)title=text(find(flex.optJSONObject(0),"text",0));if(flex.length()>1)subtitle=find(flex.optJSONObject(1),"text",0);}if(subtitle!=null){JSONArray runs=subtitle.optJSONArray("runs");if(runs!=null)for(int i=0;i<runs.length();i++){JSONObject run=runs.optJSONObject(i),browse=run==null?null:find(run,"browseEndpoint",0);if(browse!=null&&browse.optString("browseId").startsWith("UC")){if(!artist.isEmpty())artist+=", ";artist+=run.optString("text");}}}
  if(title.isBlank())return null;JSONObject thumb=find(item,"musicThumbnailRenderer",0);String image="";JSONObject thumbnails=thumb==null?item.optJSONObject("thumbnail"):thumb.optJSONObject("thumbnail");JSONArray images=thumbnails==null?null:thumbnails.optJSONArray("thumbnails");if(images!=null)for(int i=0;i<images.length();i++){JSONObject imageEntry=images.optJSONObject(i);if(imageEntry==null)continue;String url=imageEntry.optString("url");if(Artwork.safeUrl(url))image=url;}return new Track(id,title,artist,0,true,image);
 }
 private static boolean musicCredit(Object node,int depth){if(node==null||depth>16)return false;if(node instanceof JSONObject){JSONObject object=(JSONObject)node;String type=object.optString("pageType");if(type.equals("MUSIC_PAGE_TYPE_ARTIST")||type.equals("MUSIC_PAGE_TYPE_ALBUM"))return true;for(Iterator<String> keys=object.keys();keys.hasNext();)if(musicCredit(object.opt(keys.next()),depth+1))return true;}else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<Math.min(50,array.length());i++)if(musicCredit(array.opt(i),depth+1))return true;}return false;}
 static JSONObject find(Object node,String key,int depth){if(node==null||depth>20)return null;if(node instanceof JSONObject){JSONObject object=(JSONObject)node;JSONObject result=object.optJSONObject(key);if(result!=null)return result;for(Iterator<String> keys=object.keys();keys.hasNext();){result=find(object.opt(keys.next()),key,depth+1);if(result!=null)return result;}}else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<Math.min(100,array.length());i++){JSONObject result=find(array.opt(i),key,depth+1);if(result!=null)return result;}}return null;}
 private static String text(JSONObject object){if(object==null)return "";if(object.has("simpleText"))return object.optString("simpleText");StringBuilder text=new StringBuilder();JSONArray runs=object.optJSONArray("runs");if(runs!=null)for(int i=0;i<runs.length();i++)text.append(runs.optJSONObject(i).optString("text"));return text.toString();}
 static List<String> playlists(JSONObject root){LinkedHashSet<String> ids=new LinkedHashSet<>();playlistIds(root,ids,0);return new ArrayList<>(ids).subList(0,Math.min(2,ids.size()));}
 private static void playlistIds(Object node,Set<String> ids,int depth){if(depth>32||node==null||ids.size()>=2)return;if(node instanceof JSONObject){JSONObject object=(JSONObject)node,card=object.optJSONObject("musicTwoRowItemRenderer");if(card!=null){JSONObject endpoint=find(card.optJSONObject("navigationEndpoint"),"browseEndpoint",0);String id=endpoint==null?"":endpoint.optString("browseId");if(id.matches("VL[A-Za-z0-9_-]{5,150}"))ids.add(id);else{JSONObject watch=find(card.optJSONObject("navigationEndpoint"),"watchPlaylistEndpoint",0);String playlist=watch==null?"":watch.optString("playlistId");if(playlist.matches("[A-Za-z0-9_-]{5,150}"))ids.add(playlist);}return;}for(Iterator<String> keys=object.keys();keys.hasNext();)playlistIds(object.opt(keys.next()),ids,depth+1);}else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<Math.min(200,array.length());i++)playlistIds(array.opt(i),ids,depth+1);}}
}
